&lt;ActionGrid&gt;
  &lt;Settings&gt;
    &lt;Version&gt;5.27.0&lt;/Version&gt;
    &lt;Build&gt;5.27.144&lt;/Build&gt;
    &lt;CurrentContext&gt;ExportImport&lt;/CurrentContext&gt;
    &lt;ModuleId&gt;852&lt;/ModuleId&gt;
    &lt;DataSource&gt;{&quot;DefinitionId&quot;:&quot;SqlQuery&quot;,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;;WITH Parametri AS (
    SELECT
        [Initializari:ZileLucratoare_old(Anul = [GetOrSession:YearV],Luna = [GetOrSession:MonthV])] AS ZileLucratoare
)

SELECT
    a.Id,
    a.Marca,
    a.Nume,
    a.CodSucursala,
    p.ZileLucratoare,

    ISNULL(co.ZileCOLuna, 0) AS ZileCO,
    ISNULL(cm.ZileCMLuna, 0) AS ZileCM,

    zl.ZileLucrate,

    -------------------------------------------------
    -- Tip exceptie
    -------------------------------------------------
    CASE
        WHEN ISNULL(co.ZileCOLuna,0) + ISNULL(cm.ZileCMLuna,0) &amp;gt; p.ZileLucratoare
            THEN &#39;DEPASIRE_ZILE&#39;

        WHEN ISNULL(co.ZileCOLuna,0) &amp;gt; 0 
         AND ISNULL(cm.ZileCMLuna,0) &amp;gt; 0
         AND ISNULL(co.ZileCOLuna,0) + ISNULL(cm.ZileCMLuna,0) = p.ZileLucratoare
            THEN &#39;CO_CM&#39;

        WHEN ISNULL(co.ZileCOLuna,0) &amp;gt;= p.ZileLucratoare
            THEN &#39;CO&#39;

        WHEN ISNULL(cm.ZileCMLuna,0) &amp;gt;= p.ZileLucratoare
            THEN &#39;CM&#39;
    END AS TipExceptie,

    -------------------------------------------------
    -- Detalii explicative
    -------------------------------------------------
    CASE
        WHEN ISNULL(co.ZileCOLuna,0) + ISNULL(cm.ZileCMLuna,0) &amp;gt; p.ZileLucratoare
            THEN &#39;Depasire zile lucratoare (CO + CM &amp;gt; Zile luna)&#39;

        WHEN ISNULL(co.ZileCOLuna,0) &amp;gt; 0 
         AND ISNULL(cm.ZileCMLuna,0) &amp;gt; 0
         AND ISNULL(co.ZileCOLuna,0) + ISNULL(cm.ZileCMLuna,0) = p.ZileLucratoare
            THEN &#39;CO + CM = Zile lucratoare&#39;

        WHEN ISNULL(co.ZileCOLuna,0) &amp;gt;= p.ZileLucratoare
            THEN &#39;Concediu de odihna integral&#39;

        WHEN ISNULL(cm.ZileCMLuna,0) &amp;gt;= p.ZileLucratoare
            THEN &#39;Concediu medical integral&#39;
    END AS Detalii


FROM app.Salariat a

CROSS JOIN Parametri p

-----------------------------------------------------------
-- Concediu de Odihna
-----------------------------------------------------------
OUTER APPLY (
    SELECT
        SUM(
            CASE 
                WHEN c.Interval1DatadeInceput IS NOT NULL
                 AND MONTH(c.Interval1DatadeInceput) = @Luna
                 AND YEAR(c.Interval1DatadeInceput) = @Anul
                THEN ISNULL(c.NrZileCO1,0)
                ELSE 0
            END +

            CASE 
                WHEN c.Interval2DatadeInceput IS NOT NULL
                 AND MONTH(c.Interval2DatadeInceput) = @Luna
                 AND YEAR(c.Interval2DatadeInceput) = @Anul
                THEN ISNULL(c.NrZileCO2,0)
                ELSE 0
            END +

            CASE 
                WHEN c.Interval3DatadeInceput IS NOT NULL
                 AND MONTH(c.Interval3DatadeInceput) = @Luna
                 AND YEAR(c.Interval3DatadeInceput) = @Anul
                THEN ISNULL(c.NrZileCO3,0)
                ELSE 0
            END
        ) AS ZileCOLuna
    FROM app.ConcediudeOdihna c
    WHERE c.Marca = a.Marca
      AND c.CodSucursala = @CodSucursala
) co

-----------------------------------------------------------
-- Concediu Medical
-----------------------------------------------------------
OUTER APPLY (
    SELECT
        SUM(m.TotZileLucratoare) AS ZileCMLuna
    FROM app.ConcediuMedical m
    WHERE m.Marca = a.Marca
      AND m.CodSucursala = @CodSucursala
      AND m.AnulDePlata = @Anul
      AND m.LunaDePlata = @Luna
) cm

-----------------------------------------------------------
-- Zile lucrate
-----------------------------------------------------------
CROSS APPLY (
    SELECT
        CASE
            WHEN p.ZileLucratoare
                 - ISNULL(co.ZileCOLuna,0)
                 - ISNULL(cm.ZileCMLuna,0) &amp;lt;= 0
            THEN 0
            ELSE p.ZileLucratoare
                 - ISNULL(co.ZileCOLuna,0)
                 - ISNULL(cm.ZileCMLuna,0)
        END AS ZileLucrate
) zl

-----------------------------------------------------------
-- Filtru exceptii
-----------------------------------------------------------
WHERE zl.ZileLucrate = 0
  AND a.Anul = @Anul
  AND a.Luna = @Luna
  AND a.CodSucursala = @CodSucursala

ORDER BY
    a.Marca,
    a.Nume&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;IdColumn&quot;:&quot;Marca&quot;,&quot;SqlQueryColumns&quot;:&quot;&quot;,&quot;SqlQueryInsert&quot;:&quot;&quot;,&quot;SqlQueryUpdate&quot;:&quot;&quot;,&quot;SqlQueryDelete&quot;:&quot;&quot;,&quot;AddUrl&quot;:&quot;&quot;,&quot;EditUrl&quot;:&quot;&quot;,&quot;ViewUrl&quot;:&quot;&quot;},&quot;Fields&quot;:[{&quot;Title&quot;:&quot;Id&quot;,&quot;Name&quot;:&quot;Id&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;Marca&quot;,&quot;Name&quot;:&quot;Marca&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;Nume&quot;,&quot;Name&quot;:&quot;Nume&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;CodSucursala&quot;,&quot;Name&quot;:&quot;CodSucursala&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;ZileLucratoare&quot;,&quot;Name&quot;:&quot;ZileLucratoare&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;ZileCO&quot;,&quot;Name&quot;:&quot;ZileCO&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;ZileCM&quot;,&quot;Name&quot;:&quot;ZileCM&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;ZileLucrate&quot;,&quot;Name&quot;:&quot;ZileLucrate&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;TipExceptie&quot;,&quot;Name&quot;:&quot;TipExceptie&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;Detalii&quot;,&quot;Name&quot;:&quot;Detalii&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null}]}&lt;/DataSource&gt;
    &lt;ShowTitle&gt;True&lt;/ShowTitle&gt;
    &lt;NoDataMessage&gt;Nu exista exceptii de lichidare.&lt;/NoDataMessage&gt;
    &lt;AditionalHtmlHeader /&gt;
    &lt;OnInitJs /&gt;
    &lt;OnRefreshJs /&gt;
    &lt;EnableEmbed&gt;False&lt;/EnableEmbed&gt;
    &lt;ShowCondition /&gt;
    &lt;SearchPlaceholder&gt;Search&lt;/SearchPlaceholder&gt;
    &lt;SearchDelayTime&gt;300&lt;/SearchDelayTime&gt;
    &lt;TableHeight /&gt;
    &lt;PagerStyle&gt;TouchFriendly&lt;/PagerStyle&gt;
    &lt;DisplayMode&gt;Always&lt;/DisplayMode&gt;
    &lt;PopupWidth /&gt;
